WITH filtered AS (SELECT *, LENGTH(channel) AS channel_length, CEIL(discount_pct) AS discount_pct_whole, COALESCE(channel, 'N/A') AS resolved_channel FROM promotions WHERE channel NOT IN ('store', 'partner', 'web')) SELECT id, channel, promo_code, starts_on, ends_on, discount_pct, channel_length, discount_pct_whole, resolved_channel, AVG(discount_pct) OVER (PARTITION BY promo_code ORDER BY discount_pct, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS discount_pct_avg_5, LAG(discount_pct, 1) OVER w_part AS prev_discount_pct FROM filtered WINDOW w_part AS (PARTITION BY channel, promo_code ORDER BY ends_on, id)
